namespace sv_66077433737446029f486180427bcc29.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

/// <summary>
/// In-memory implementation for demonstration purposes.
/// </summary>
public class InMemorySettingsService : ISettingsService
{
    private UserProfile _profile = new("Jane Doe", "jane@example.com", "https://i.pravatar.cc/150?img=5", "Software developer and coffee enthusiast.");
    private NotificationPrefs _notifications = new(true, false, true, new List<string> { "marketing" });
    private SecuritySettings _security = new(false, DateTime.UtcNow.AddDays(-30), new List<ActiveSession>
    {
        new("sess-1", "Chrome on Windows", "New York, US", DateTime.UtcNow.AddMinutes(-5)),
        new("sess-2", "Safari on iPhone", "New York, US", DateTime.UtcNow.AddHours(-2)),
        new("sess-3", "Firefox on Linux", "London, UK", DateTime.UtcNow.AddDays(-1))
    });
    private AppearanceSettings _appearance = new("System", "Medium", "English", false);

    public Task<UserProfile> GetProfileAsync() => Task.FromResult(_profile);
    public Task SaveProfileAsync(UserProfile profile) { _profile = profile; return Task.CompletedTask; }
    public Task<NotificationPrefs> GetNotificationPrefsAsync() => Task.FromResult(_notifications);
    public Task SaveNotificationPrefsAsync(NotificationPrefs prefs) { _notifications = prefs; return Task.CompletedTask; }
    public Task<SecuritySettings> GetSecuritySettingsAsync() => Task.FromResult(_security);

    public Task ChangePasswordAsync(string currentPassword, string newPassword)
    {
        _security = _security with { LastPasswordChange = DateTime.UtcNow };
        return Task.CompletedTask;
    }

    public Task RevokeSessionAsync(string sessionId)
    {
        _security = _security with
        {
            Sessions = _security.Sessions.Where(s => s.Id != sessionId).ToList()
        };
        return Task.CompletedTask;
    }

    public Task<AppearanceSettings> GetAppearanceAsync() => Task.FromResult(_appearance);
    public Task SaveAppearanceAsync(AppearanceSettings settings) { _appearance = settings; return Task.CompletedTask; }
}

@namespace sv_66077433737446029f486180427bcc29.Components.Pages.Settings

<nav class="settings-sidebar">
    @foreach (var section in Sections)
    {
        <button class="sidebar-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
            <span class="sidebar-icon">@GetIcon(section)</span>
            <span class="sidebar-label">@section</span>
        </button>
    }
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_66077433737446029f486180427bcc29.Components.Pages.Settings
@using sv_66077433737446029f486180427bcc29.Services

<div class="settings-section">
    <h2>Profile</h2>

    <div class="avatar-preview">
        <img src="@AvatarUrl" alt="Avatar" class="avatar-image" />
        <p class="avatar-url">@AvatarUrl</p>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="DisplayName" class="form-input" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="Email" class="form-input" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" @bind="Bio" class="form-input form-textarea" rows="4"></textarea>
    </div>

    <div class="form-group">
        <label for="avatarUrl">Avatar URL</label>
        <input id="avatarUrl" type="url" @bind="AvatarUrl" class="form-input" />
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
        <button class="btn btn-secondary" @onclick="Discard">Discard Changes</button>
    </div>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="toast toast-success">@_message</div>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Bio { get; set; } = "";
    private string AvatarUrl { get; set; } = "";
    private string? _message;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_initialized)
        {
            LoadFromProfile(Profile);
            _initialized = true;
        }
    }

    private bool _initialized;

    private void LoadFromProfile(UserProfile profile)
    {
        DisplayName = profile.DisplayName;
        Email = profile.Email;
        Bio = profile.Bio;
        AvatarUrl = profile.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        _message = "Profile saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private void Discard()
    {
        if (Profile is not null)
            LoadFromProfile(Profile);
        _message = null;
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        _message = null;
        StateHasChanged();
    }
}

@namespace sv_66077433737446029f486180427bcc29.Components.Pages.Settings
@using sv_66077433737446029f486180427bcc29.Services

<div class="settings-section">
    <h2>Notifications</h2>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="EmailNotifications" class="toggle-input" />
            <span class="toggle-switch"></span>
            Email Notifications
        </label>
    </div>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="PushNotifications" class="toggle-input" />
            <span class="toggle-switch"></span>
            Push Notifications
        </label>
    </div>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="WeeklyDigest" class="toggle-input" />
            <span class="toggle-switch"></span>
            Weekly Digest
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in AllChannels)
        {
            <label class="channel-item">
                <input type="checkbox"
                       checked="@MutedChannels.Contains(channel)"
                       @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                <span>@channel</span>
            </label>
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
    </div>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="toast toast-success">@_message</div>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications { get; set; }
    private bool PushNotifications { get; set; }
    private bool WeeklyDigest { get; set; }
    private List<string> MutedChannels { get; set; } = new();

    private static readonly string[] AllChannels = { "general", "marketing", "engineering", "support", "announcements" };

    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedChannels = new List<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    private string? _message;

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await OnSave.InvokeAsync(updated);
        _message = "Preferences saved!";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        _message = null;
        StateHasChanged();
    }
}

@namespace sv_66077433737446029f486180427bcc29.Components.Pages.Settings
@using sv_66077433737446029f486180427bcc29.Services

<div class="settings-section">
    <h2>Security</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
            <span>🔑 Change Password</span>
            <span class="panel-toggle">@(_passwordExpanded ? "▲" : "▼")</span>
        </button>

        @if (_passwordExpanded)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPwd">Current Password</label>
                    <input id="currentPwd" type="password" @bind="_currentPassword" class="form-input" />
                </div>
                <div class="form-group">
                    <label for="newPwd">New Password</label>
                    <input id="newPwd" type="password" @bind="_newPassword" class="form-input" />
                </div>
                <div class="form-group">
                    <label for="confirmPwd">Confirm Password</label>
                    <input id="confirmPwd" type="password" @bind="_confirmPassword" class="form-input" />
                </div>
                @if (!string.IsNullOrEmpty(_passwordError))
                {
                    <div class="toast toast-error">@_passwordError</div>
                }
                @if (!string.IsNullOrEmpty(_passwordSuccess))
                {
                    <div class="toast toast-success">@_passwordSuccess</div>
                }
                <button class="btn btn-primary" @onclick="ChangePasswordAsync">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="security-row">
        <div class="security-info">
            <h3>Two-Factor Authentication</h3>
            <span class="status-indicator @(Settings?.TwoFactorEnabled == true ? "status-on" : "status-off")">
                @(Settings?.TwoFactorEnabled == true ? "● Enabled" : "○ Disabled")
            </span>
        </div>
        @if (Settings?.LastPasswordChange.HasValue == true)
        {
            <p class="meta-text">Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <h3>Active Sessions</h3>
    @if (Settings?.Sessions.Any() == true)
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Settings.Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@FormatLastActive(session.LastActive)</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }

    <!-- Revoke Confirmation Dialog -->
    @if (_sessionToRevoke is not null)
    {
        <div class="dialog-overlay" @onclick="CancelRevoke">
            <div class="dialog" @onclick:stopPropagation="true">
                <h3>Revoke Session?</h3>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                <div class="dialog-actions">
                    <button class="btn btn-danger" @onclick="RevokeAsync">Yes, Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
