@namespace sv_66077433737446029f486180427bcc29.Components.Pages.Settings
@using sv_66077433737446029f486180427bcc29.Services

<div class="settings-section">
    <h2>Appearance</h2>

    <!-- Theme -->
    <div class="form-group">
        <label class="form-label">Theme</label>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-item">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(Theme == theme)"
                           @onchange="() => Theme = theme" />
                    @theme
                </label>
            }
        </div>
    </div>

    <!-- Font Size -->
    <div class="form-group">
        <label class="form-label">Font Size</label>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(FontSize == size)"
                           @onchange="() => FontSize = size" />
                    @size
                </label>
            }
        </div>
    </div>

    <!-- Language -->
    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="Language" class="form-input">
            <option value="English">English</option>
            <option value="Spanish">Spanish</option>
            <option value="French">French</option>
            <option value="German">German</option>
            <option value="Japanese">Japanese</option>
        </select>
    </div>

    <!-- Compact Mode -->
    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="CompactMode" class="toggle-input" />
            <span class="toggle-switch"></span>
            Compact Mode
        </label>
    </div>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Preview</h4>
        <p>This is how your content will look with the selected settings.</p>
        <button class="btn btn-primary">Sample Button</button>
        <p class="meta-text">Language: @Language | Compact: @(CompactMode ? "On" : "Off")</p>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
    </div>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="toast toast-success">@_message</div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme { get; set; } = "System";
    private string FontSize { get; set; } = "Medium";
    private string Language { get; set; } = "English";
    private bool CompactMode { get; set; }

    private bool _initialized;
    private string? _message;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{Theme.ToLowerInvariant()} preview-font-{FontSize.ToLowerInvariant()}";
        if (CompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
        _message = "Appearance saved!";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        _message = null;
        StateHasChanged();
    }
}

