/* Settings Dashboard Styles */

.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: var(--bs-gray-100, #f8f9fa);
    border-right: 1px solid var(--bs-gray-300, #dee2e6);
    padding: 1.5rem 0;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    border: none;
    background: transparent;
    cursor: pointer;
    font-size: 0.95rem;
    color: var(--bs-gray-700, #495057);
    text-align: left;
    width: 100%;
    transition: background 0.15s, color 0.15s;
}

.sidebar-item:hover {
    background: var(--bs-gray-200, #e9ecef);
}

.sidebar-item.active {
    background: var(--bs-primary, #0d6efd);
    color: white;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* Content Area */
.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    font-weight: 600;
}

/* Forms */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    font-size: 0.9rem;
    color: var(--bs-gray-700, #495057);
}

.form-label {
    display: block;
    margin-bottom: 0.5rem;
    font-weight: 500;
    font-size: 0.9rem;
}

.form-input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--bs-gray-300, #dee2e6);
    border-radius: 0.375rem;
    font-size: 0.95rem;
    transition: border-color 0.15s;
}

.form-input:focus {
    outline: none;
    border-color: var(--bs-primary, #0d6efd);
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.15);
}

.form-textarea {
    resize: vertical;
    min-height: 80px;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Buttons */
.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: opacity 0.15s;
}

.btn:hover {
    opacity: 0.85;
}

.btn-primary {
    background: var(--bs-primary, #0d6efd);
    color: white;
}

.btn-secondary {
    background: var(--bs-gray-200, #e9ecef);
    color: var(--bs-gray-700, #495057);
}

.btn-danger {
    background: var(--bs-danger, #dc3545);
    color: white;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* Avatar */
.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: var(--bs-gray-100, #f8f9fa);
    border-radius: 0.5rem;
}

.avatar-image {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid var(--bs-gray-300, #dee2e6);
}

.avatar-url {
    font-size: 0.8rem;
    color: var(--bs-gray-600, #6c757d);
    word-break: break-all;
}

/* Toggles */
.toggle-group {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-input {
    width: 2.5rem;
    height: 1.25rem;
    appearance: none;
    background: var(--bs-gray-400, #ced4da);
    border-radius: 1rem;
    position: relative;
    cursor: pointer;
    transition: background 0.2s;
}

.toggle-input::before {
    content: '';
    position: absolute;
    top: 2px;
    left: 2px;
    width: 1rem;
    height: 1rem;
    background: white;
    border-radius: 50%;
    transition: transform 0.2s;
}

.toggle-input:checked {
    background: var(--bs-primary, #0d6efd);
}

.toggle-input:checked::before {
    transform: translateX(1.25rem);
}

/* Channels */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    background: var(--bs-gray-100, #f8f9fa);
    border-radius: 0.375rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.9rem;
    cursor: pointer;
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid var(--bs-gray-300, #dee2e6);
    border-radius: 0.5rem;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.875rem 1.25rem;
    border: none;
    background: var(--bs-gray-100, #f8f9fa);
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid var(--bs-gray-200, #e9ecef);
}

/* Security */
.security-row {
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: var(--bs-gray-100, #f8f9fa);
    border-radius: 0.5rem;
}

.security-info {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.security-info h3 {
    margin: 0;
}

.status-indicator {
    font-size: 0.85rem;
    font-weight: 500;
}

.status-on {
    color: var(--bs-success, #198754);
}

.status-off {
    color: var(--bs-gray-500, #adb5bd);
}

.meta-text {
    font-size: 0.8rem;
    color: var(--bs-gray-600, #6c757d);
    margin-top: 0.5rem;
}

.badge {
    font-size: 0.75rem;
    padding: 0.2rem 0.6rem;
