+    text-align: left;
+    border-bottom: 1px solid var(--bs-gray-200, #e9ecef);
+}
+
+.sessions-table th {
+    font-weight: 600;
+    color: var(--bs-gray-600, #6c757d);
+    font-size: 0.8rem;
+    text-transform: uppercase;
+    letter-spacing: 0.5px;
+}
+
+/* Dialog */
+.dialog-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.dialog {
+    background: white;
+    border-radius: 0.75rem;
+    padding: 2rem;
+    max-width: 420px;
+    width: 90%;
+    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.2);
+}
+
+.dialog h3 {
+    margin-top: 0;
+}
+
+.dialog-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.5rem;
+}
+
+/* Radio Groups */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+}
+
+.radio-item {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+    font-size: 0.9rem;
+}
+
+/* Appearance Preview */
+.preview-area {
+    margin-top: 1.5rem;
+    padding: 1.5rem;
+    border: 2px dashed var(--bs-gray-300, #dee2e6);
+    border-radius: 0.5rem;
+    transition: all 0.3s;
+}
+
+.preview-theme-dark {
+    background: #1a1a2e;
+    color: #eaeaea;
+    border-color: #444;
+}
+
+.preview-theme-light {
+    background: #ffffff;
+    color: #212529;
+}
+
+.preview-theme-system {
+    background: #f0f4f8;
+    color: #333;
+}
+
+.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.2rem;
+}
+
+.preview-compact {
+    padding: 0.75rem;
+    line-height: 1.2;
+}
+
+/* Toast */
+.toast {
+    margin-top: 1rem;
+    padding: 0.75rem 1rem;
+    border-radius: 0.375rem;
+    font-size: 0.9rem;
+    animation: slideIn 0.3s ease;
+}
+
+.toast-success {
+    background: #d1e7dd;
+    color: #0f5132;
+    border: 1px solid #badbcc;
+}
+
+.toast-error {
+    background: #f8d7da;
+    color: #842029;
+    border: 1px solid #f5c2c7;
+}
+
+@keyframes slideIn {
+    from { opacity: 0; transform: translateY(-8px); }
+    to { opacity: 1; transform: translateY(0); }
+}
+
+/* Loading */
+.loading {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    padding: 3rem;
+    color: var(--bs-gray-500, #adb5bd);
+    font-size: 1.1rem;
+}
+

